// Action-type sections must capture every owned task, including ones
// assigned to other people and ones with no deadline. Applied at runtime
// because section descriptions are stored per-mode in the DB and some
// (e.g. "action items that were said I would do") would otherwise drop
// tasks like "Priya will send the contract".
const isActionSection = (title: string) => /action|follow[\s-]?up|to-?do|next steps|tasks/i.test(title);
const actionRule = ` Include EVERY task that has an owner — whoever it is (me or anyone else named in the meeting) — formatted "Owner: task (due date)" or "Owner: task (no date given)" when no deadline was mentioned. Never drop a task for lacking a deadline; never invent a date.`;
const sectionList = modeNoteSections
    .map(s => {
        const desc = (s.description?.trim() || '') + (isActionSection(s.title) ? actionRule : '');
        return desc.trim() ? `- "${s.title}": ${desc.trim()}` : `- "${s.title}"`;
    })
    .join('\n');

